		if seedOpts.force {
			if err := os.RemoveAll(outputDir); err != nil {
				return fmt.Errorf("remove forced output directory: %w", err)
			}
		} else if _, err := validateExportDirAvailable(outputDir); err != nil {
			return err
		}
	}
